INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("", 0, 0, 15, 24001, "", 30000, 0, 2, 1, 35);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("", 0, 0, 1, 91002, "", 40000, 0, 8, 100, 36);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("ぺコリーヌ", 107501, 0, 1, 91002, "今日は記念日、お祝いですね！\n焼肉、お寿司、ピザ、ケーキ～☆\nあなたとパーティできるなんて、\n幸せです～♪", 40001, 1, 8, 150, 37);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("コッコロ", 107601, 0, 2, 91002, "この記念日を迎えられたのは、\n主さまの器量の賜物\nさすがは主さまでございます\nえらい、えらい♪", 40001, 1, 8, 150, 38);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("キャル", 107801, 0, 3, 91002, "あんたもけっこうやるじゃない！\nちょっとは…割と…け、けっこう\n見直しちゃったわ\n褒めてあげる♪", 40001, 1, 8, 150, 39);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("スズメ", 107701, 0, 4, 91002, "あなたと私にとって、\n今日は特別な日\nあなたの支えがあるから、\n私は頑張れるんです！", 40001, 1, 8, 150, 40);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("タマキ", 107901, 0, 5, 91002, "今日はキミにとっての\n特別な記念日だにゃ\nキミの活躍にはいつも\n猫ながら感謝してるにゃ～♪", 40001, 1, 8, 150, 41);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("ぺコリーヌ", 107501, 0, 6, 91002, "う～かき氷食べ過ぎて、\n身体が冷えちゃいました…\nあなたの体温で温めてください！\nギューーッ♪", 40001, 2, 8, 150, 42);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("コッコロ", 107601, 0, 7, 91002, "夏は危険がいっぱいと申します…\nですが、わたくしが主さまを\nしっかりとお守りいたしますよ", 40001, 2, 8, 150, 43);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("キャル", 107801, 0, 8, 91002, "ん～なんであんたと、ひと夏を\n過ごすことになったのかな…\n結構楽しいからいいけど！\nさ、まだまだ遊ぶわよ！", 40001, 2, 8, 150, 44);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("スズメ", 107701, 0, 9, 91002, "あなたと過ごすはじめての夏…\nいまからドキドキが止まりません\n楽しくて素敵な思い出が、\nまた一つ増えるんですね♪", 40001, 2, 8, 150, 45);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("タマキ", 107901, 0, 10, 91002, "夏は一番の稼ぎ時にゃのに、\n今年はキミと過ごしたいって\n思ってるにゃ楽しい思い出\n増やしてくれるかにゃ？", 40001, 2, 8, 150, 46);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("", 0, 0, 1, 91002, "", 40003, 0, 8, 150, 57);
