INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("リリ", 125801, 0, 1, 24001, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 40011, 1, 2, 1, 321);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("クリア", 126001, 0, 2, 24001, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 40011, 1, 2, 1, 322);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("プレシア", 126101, 0, 3, 24001, "んーと。\nこれ、あげる。\nはい", 40011, 1, 2, 1, 323);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("リリ", 125801, 0, 4, 24001, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 40011, 2, 2, 1, 324);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("クリア", 126001, 0, 5, 24001, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 40011, 2, 2, 1, 325);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("プレシア", 126101, 0, 6, 24001, "お兄。\nきてくれて、うれしい", 40011, 2, 2, 1, 326);
